84: static void set_widget_positions()
85: {
86:     button_t **button_list[] = { &enter_event_btn,
87: 				  &practice_btn,
88: 				  &credits_btn,
89: 				  &quit_btn };
90:     int w = getparam_x_resolution();
91:     int h = getparam_y_resolution();
92:     int box_height;
93:     int box_max_y;
94:     int top_y;
95:     int bottom_y;
96:     int num_buttons = sizeof( button_list ) / sizeof( button_list[0] );
97:     int i;
98:     int tot_button_height = 0;
99:     int button_sep =0;
100:     int cur_y_pos;
101: 
102:     box_height = 210;
103:     box_max_y = h - 128;
104: 
105:     bottom_y = 0.4*h - box_height/2;
106: 
107:     if ( bottom_y + box_height > box_max_y ) {
108: 	bottom_y = box_max_y - box_height;
109:     }
110: 
111:     top_y = bottom_y + box_height;
112: 
113:     for (i=0; i<num_buttons; i++) {
114: 	tot_button_height += button_get_height( *button_list[i] );
115:     }
116: 
117:     if ( num_buttons > 1 ) {
118: 	button_sep = ( top_y - bottom_y - tot_button_height ) / 
119: 	    ( num_buttons - 1 );
120: 	button_sep = max( 0, button_sep );
121:     }
122: 
123:     cur_y_pos = top_y;
124:     for (i=0; i<num_buttons; i++) {
125: 	cur_y_pos -= button_get_height( *button_list[i] );
126: 	button_set_position( 
127: 	    *button_list[i],
128: 	    make_point2d( w/2.0 - button_get_width( *button_list[i] )/2.0,
129: 			  cur_y_pos ) );
130: 	cur_y_pos -= button_sep;
131:     }
132: }
